import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1195, own='cte_118.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 821 Welding II ----
H("821.d.1.A",3,"Marisol wants to weld pipelines after graduation. She reads the Texas college catalog to see which math, blueprint and certification courses lead to that job. She is exploring:","academic knowledge and skills needed for postsecondary education and careers",["only the cafeteria menu","only the football schedule","only the parking rules"],"Course requirements shape the path.")
H("821.d.1.A",4,"Which plan best prepares a high school welding student for a two-year welding technology program?","take geometry and blueprint reading while earning an entry-level AWS credential",["skip math and focus on art only","avoid any shop classes","wait until after graduation to start"],"Math, print reading and credentials transfer.")
H("821.d.1.B",3,"A fabrication customer calls twice about a late handrail order. The owner tells the crew that meeting delivery dates and quality is what keeps clients coming back. This shows employers' expectations that foster:","positive customer satisfaction",["higher shop rent","shorter lunch breaks","less paperwork"],"Delivery and quality satisfy customers.")
H("821.d.1.B",4,"A welder finishes a trailer hitch ahead of schedule but notices a crooked bracket. To meet the employer's expectations she should:","fix the bracket before it leaves the shop",["ship it and hope no one notices","blame the cutter","wait for a complaint"],"Quality is part of satisfaction.")
H("821.d.1.C",3,"Devon arrives ten minutes early, puts on his PPE without being reminded, and thanks the lead for feedback. Which workplace standard is he showing?","dependability and respect",["carelessness","impatience","secrecy"],"Reliability and courtesy are professional standards.")
H("821.d.1.C",4,"A coworker keeps leaving cut-off scraps on the floor around her booth. Which standard is she missing?","keeping a safe, orderly work area",["wearing a belt","speaking quietly","parking neatly"],"Housekeeping is a professional standard.")
H("821.d.1.D",3,"At the start of each semester, Jada rereads her written goal to earn a structural welding certificate and checks which steps are done. She is:","evaluating her personal career goals",["ordering supplies","grading a test","tuning equipment"],"Review of goals keeps a plan on track.")
H("821.d.1.D",4,"After failing a bend test, Jada decides to add practice time and ask the instructor for tips. This shows an evaluation that leads to:","revising the plan to reach the career goal",["abandoning the career","hiding the result","blaming the equipment"],"Evaluate, then adjust.")
H("821.d.1.E",3,"Before starting a rush job, Eli repeats the drawing number, weld size and due date back to the supervisor. He does this to:","clarify objectives and avoid mistakes",["delay the work","impress a visitor","change the order"],"Repeating details confirms understanding.")
H("821.d.1.E",4,"The work order says 'weld the frame' but gives no joint type. The best communication step is to:","ask the supervisor which weld is required",["guess and begin","skip the frame","use the cheapest rod"],"Clarify before welding.")
H("821.d.1.F",3,"A shop posts safety data sheets, requires eye protection at the grinders and runs fire drills. These steps support:","health and safety requirements set by OSHA",["marketing goals","payroll rules","parking rules"],"OSHA sets workplace safety standards.")
H("821.d.1.F",4,"A new hire sees an unlabeled spray bottle near the welding table. The best safety action is to:","report it and avoid using it until it is identified",["spray it on the metal","pour it down the drain","take it home"],"Unknown chemicals can be hazardous.")
H("821.d.2.A",3,"A customer who speaks little English visits the shop to ask about a gate. The welder uses simple words, a sketch and a tape measure to confirm the size. This demonstrates:","effective communication with people from varied backgrounds",["ignoring the customer","rushing the sale","using only jargon"],"Sketches and simple words bridge gaps.")
H("821.d.2.A",4,"When talking with a new supplier whose first language differs, the best habit is to:","speak clearly and confirm understanding with a written note",["talk faster","use slang","avoid the topic"],"Confirming prevents errors.")
H("821.d.2.B",3,"A job needs 18 feet of 2-inch tube at $3.50 per foot plus $42 of rod. The estimated material cost is:","$105",["$63","$84","$147"],"18 × 3.50 = 63, plus 42 = 105.")
H("821.d.2.B",4,"A fabricator estimates 6 hours of labor at $28 per hour plus $95 in materials and adds a 10% markup to the total. The bid is:","$289.30",["$263","$273","$310"],"168 + 95 = 263; ×1.10 = 289.30.")
H("821.d.2.C",3,"A work order should list the customer, the job description, materials and due date because it:","tells everyone what to build and by when",["replaces the drawing","hides the cost","avoids planning"],"Work orders communicate the task.")
H("821.d.2.C",4,"Which sentence is the best technical writing for a work order?","Weld two 3/16 in. fillets on all joints of frame A by Friday.",["Do the frame stuff soon.","Make it look good.","Weld it however."],"Specific and measurable.")
H("821.d.2.D",3,"An apprentice reads a vernier caliper at 1.375 in. and a tape at 1 3/8 in. for the same bar. The readings:","agree, since 1.375 equals 1 3/8",["disagree by 1/8","disagree by 1/4","cannot be compared"],"3/8 = 0.375.")
H("821.d.2.D",4,"Reading a tape measure, a mark halfway between 2 1/4 in. and 2 3/8 in. is:","2 5/16 in.",["2 1/2 in.","2 3/16 in.","2 7/16 in."],"Halfway is 2 5/16.")
H("821.d.2.E",3,"To check that a fabricated corner is exactly 90 degrees, the welder should use a:","framing or combination square",["stopwatch","thermometer","scale"],"Squares check right angles.")
H("821.d.2.E",4,"Which tool best measures the leg size of a finished fillet weld?","fillet weld gauge",["feeler gauge for spark plugs","micrometer for wire","straight edge only"],"Fillet gauges show leg size.")
H("821.d.2.F",3,"A rectangular steel plate is 24 in. by 18 in. Its area is:","432 square inches",["42 square inches","84 square inches","864 square inches"],"24 × 18 = 432.")
H("821.d.2.F",4,"A rectangular tank is 4 ft long, 3 ft wide and 2 ft tall. Its volume is:","24 cubic feet",["9 cubic feet","12 cubic feet","48 cubic feet"],"4 × 3 × 2 = 24.")
H("821.d.2.G",3,"A welder cuts three pieces measuring 4 1/2, 3 3/4 and 2 1/4 inches. The total length is:","10 1/2 inches",["9 1/2 inches","10 inches","11 inches"],"4.5+3.75+2.25 = 10.5.")
H("821.d.2.G",4,"From a 12.75 in. bar, a welder cuts 4 5/8 in. The remaining length is:","8 1/8 in.",["7 7/8 in.","8 3/8 in.","8 1/4 in."],"12.75 − 4.625 = 8.125.")
H("821.d.2.H",3,"A welder uses a calculator to find the number of 7.5-inch brackets that can be cut from a 120-inch bar. The answer is:","16",["15","17","18"],"120 ÷ 7.5 = 16.")
H("821.d.2.H",4,"Which method is a reasonable check on a calculator result for 49.8 × 3.02?","estimate with 50 × 3 = 150",["use 100 × 10","add instead","ignore it"],"Estimation catches entry errors.")
H("821.d.2.I",3,"A drawing calls for a 5/8 in. hole. As a decimal, this is:","0.625 in.",["0.58 in.","0.85 in.","0.5 in."],"5 ÷ 8 = 0.625.")
H("821.d.2.I",4,"A shop caliper reads 0.4375 in. The same size as a fraction is:","7/16 in.",["3/8 in.","1/2 in.","9/16 in."],"0.4375 = 7/16.")
H("821.d.2.J",3,"A metric drawing calls for a plate 50.8 mm thick. In inches, that is:","2 in.",["1 in.","5 in.","1.5 in."],"50.8 ÷ 25.4 = 2.")
H("821.d.2.J",4,"A 3/4 in. diameter rod is about how many millimeters?","19 mm",["7.5 mm","34 mm","25 mm"],"0.75 × 25.4 ≈ 19.")
H("821.d.2.K",3,"A brace runs diagonally across a rectangular frame 3 ft by 4 ft. Using the Pythagorean theorem, its length is:","5 ft",["7 ft","6 ft","12 ft"],"3²+4²=25; √25=5.")
H("821.d.2.K",4,"A right-triangle gusset has legs of 6 in. and 8 in. The hypotenuse is:","10 in.",["14 in.","12 in.","9 in."],"36+64=100.")
H("821.d.2.L",3,"On a circle diagram, the straight line from edge to edge through the center is the:","diameter",["tangent","arc","sector"],"Diameter passes through the center.")
H("821.d.2.L",4,"A pipe diagram labels the distance from the center to the outside edge as 3 in. This distance is the:","radius",["chord","diameter","circumference"],"Radius is half the diameter.")
H("821.d.3.A",3,"Before striking an arc, Priya checks the cable insulation, ground clamp and the area for flammable rags. She is:","operating welding equipment according to safety standards",["setting a price","painting a part","packing a truck"],"Pre-use checks follow safety standards.")
H("821.d.3.A",4,"A welder sees the cable insulation worn through near the electrode holder. The correct step is to:","stop and have the cable repaired or replaced",["wrap it with tape later","keep welding","move it to a dry spot"],"Damaged cables are shock hazards.")
H("821.d.3.B",3,"A shop has used degreaser, spent flux and oily rags. Which is the proper way to handle them?","store them in labeled approved containers for licensed disposal",["pour them on the lot","throw them in the trash","burn them outside"],"Hazardous waste has rules.")
H("821.d.3.B",4,"A can of used solvent is nearly full. The environmentally correct action is to:","close it, label it and arrange hazardous waste pickup",["pour it into a floor drain","dump it in the dirt","leave it open to evaporate"],"Evaporation and drains pollute.")
H("821.d.3.C",3,"A shop sells steel cut-offs to a metal recycler each month. This practice:","conserves resources and reduces landfill waste",["raises disposal costs","wastes energy","increases pollution"],"Recycling saves material and energy.")
H("821.d.3.C",4,"Which welding material is most commonly recycled in large amounts?","scrap steel",["used gloves","slag chips","flux smoke"],"Steel scrap is widely recycled.")
H("821.d.3.D",3,"For overhead welding, a student chooses a helmet, leather jacket, gloves, cap and boots. These items make up:","personal protective equipment",["shop inventory","tool storage","a work order"],"PPE protects the welder.")
H("821.d.3.D",4,"Which choice is the best footwear when welding?","leather boots with the pant legs over the tops",["open sandals","canvas sneakers","bare feet"],"Covered leather boots shed sparks.")
H("821.d.3.E",3,"At the end of the month, Ben compares the number of near-miss reports and decides to start stricter PPE checks. He is:","evaluating health and safety skills",["ordering rods","changing prices","building a table"],"Evaluation leads to improvement.")
H("821.d.3.E",4,"An evaluation shows hearing protection is skipped at the grinders. The best improvement is to:","post a reminder and check compliance each shift",["remove the grinders","ignore it","buy louder tools"],"Consistent checks raise compliance.")
H("821.d.4.A",3,"Before cutting steel, a welder reads a drawing that shows lengths, hole sizes and notes. This shows knowledge of:","engineering drawings",["menu boards","bus maps","phone books"],"Drawings communicate design.")
H("821.d.4.A",4,"The title block of an engineering drawing usually gives the:","part name, scale and drawing number",["welder's lunch order","shop's payroll","customer's phone password"],"Title blocks identify the drawing.")
H("821.d.4.B",3,"A drawing shows the front, top and right-side views of a bracket as flat, separate pictures. These are:","orthographic views",["isometric views only","photographs","cutaway models"],"Orthographic views are flat projections.")
H("821.d.4.B",4,"Which view shows three faces of a part in one picture, with width, depth and height at an angle?","isometric",["top","front","side"],"Isometric views show all three dimensions.")
H("821.d.4.C",3,"A welder reads a chart that lists plate thickness and recommended amperage. This is:","interpreting a chart",["painting a part","cutting a shape","calling a vendor"],"Charts give specifications.")
H("821.d.4.C",4,"On a print, a dashed line most commonly represents:","a hidden edge",["a welding arc","a weld bead","the center of the shop"],"Dashed lines show hidden features.")
H("821.d.4.D",3,"On a drawing, a triangle under the reference line, a number to its left and an arrow pointing to the joint are parts of the:","welding symbol",["title block","scale bar","bill of materials"],"The symbol communicates the weld.")
H("821.d.4.D",4,"In a welding symbol, a small flag at the bend of the reference line means the weld is to be made:","in the field",["in the shop only","underwater","on a sheet only"],"Field weld flag.")
H("821.d.4.E",3,"Two plates lying flat with one overlapping the other form a:","lap joint",["butt joint","corner joint","edge joint"],"Overlapping plates are a lap joint.")
H("821.d.4.E",4,"Two plates placed end to end in the same plane form a:","butt joint",["lap joint","tee joint","corner joint"],"End-to-end in-line plates are butt joints.")
H("821.d.4.F",3,"A weld made on a plate lying horizontally, with the welder looking down on the joint, is in the:","flat position",["vertical position","overhead position","horizontal position"],"Flat means welded from above.")
H("821.d.4.F",4,"Welding upward on a joint standing on end is in the:","vertical position",["flat position","overhead position","horizontal position"],"Vertical joints are welded up or down.")
H("821.d.4.G",3,"A triangular weld at the intersection of two plates at right angles is a:","fillet weld",["groove weld","plug weld","spot weld"],"Fillets are triangular.")
H("821.d.4.G",4,"A weld made in a hole in the top plate to join it to the one below is a:","plug weld",["fillet weld","groove weld","flange weld"],"Plug welds fill a hole.")
H("821.d.5.A",3,"After welding a trailer frame, a lead inspects the welds with a light and a gauge to look for cracks, undercut and incomplete fusion. This is:","a weld inspection process",["a painting step","a packing step","a pricing step"],"Visual inspection checks quality.")
H("821.d.5.A",4,"The first and most common weld inspection method is:","visual inspection",["radiography","magnetic particle only","ultrasonic only"],"Visual inspection comes first.")
H("821.d.5.B",3,"An inspector uses a code book to decide whether a pipeline weld's undercut is acceptable. She is:","interpreting a welding code",["setting a price","tuning a tool","ordering lunch"],"Codes define acceptance.")
H("821.d.5.B",4,"A welding code mainly provides:","minimum requirements for weld quality and procedure",["a list of prices","a shop schedule","uniform colors"],"Codes set standards.")

H("821.d.6.A",3,"Rosa is about to light a cutting torch in a corner of the shop. Which action follows safe operating practice?","check that no flammables are nearby and use a striker to light it",["light it with a pocket lighter near the hose","point it toward a coworker","leave the cylinders lying down"],"Clear area and proper striker.")
H("821.d.6.A",4,"After finishing a cut, the operator should shut off the torch by:","closing the fuel valve first, then the oxygen valve",["leaving both valves open","closing only the oxygen","dropping the torch"],"Fuel off first ends the flame safely.")
H("821.d.6.B",3,"A cylinder cart carrying oxygen and fuel gas needs to be moved across the shop. The safe method is to:","chain the cylinders upright and cap them",["roll them on their sides","carry them by the valve","stack them flat"],"Secured, capped cylinders are stable.")
H("821.d.6.B",4,"If a cylinder valve will not close and gas hisses out, the first response is to:","move it outdoors away from ignition and notify the supervisor",["strike it with a hammer","light it to burn off","hide it in a closet"],"Leaks require evacuation and reporting.")
H("821.d.6.C",3,"On an oxy-fuel setup, the gauges that show cylinder contents and working pressure are part of the:","regulators",["torch tip","cutting table","flux box"],"Regulators control pressure.")
H("821.d.6.C",4,"The device installed between the hoses and the torch to stop a flame from traveling backward is a:","flashback arrestor",["gloves","slag hammer","nozzle brush"],"Arrestors stop flashbacks.")
H("821.d.6.D",3,"Before lighting the torch, the operator opens each torch valve briefly to clear the lines. This step is called:","purging",["tacking","peening","grinding"],"Purging clears air and mixed gas.")
H("821.d.6.D",4,"A common correct order during set-up is to:","open the cylinder valve slowly, then set the regulator pressure",["open it fully and fast","set the pressure before attaching the regulator","skip leak testing"],"Slow opening protects the regulator.")
H("821.d.6.E",3,"A student finds that a 1 in. plate needs a different tip and pressure than a 1/4 in. plate. The factor affecting the cut is the metal's:","thickness",["paint color","brand name","weight of the cart"],"Thicker metal needs more heat and oxygen.")
H("821.d.6.E",4,"Which condition makes an oxy-fuel cut less clean?","heavy rust and mill scale on the surface",["clean bare steel","a sharp tip","a steady travel speed"],"Scale interferes with preheating.")
H("821.d.6.F",3,"To start a cut in the middle of a plate without an edge, the operator uses a technique called:","piercing",["peening","tacking","bending"],"Piercing starts a hole in the plate interior.")
H("821.d.6.F",4,"To cut a clean straight line, the operator should:","guide the torch along a straightedge at a steady speed",["move as fast as possible","hold the tip against the plate","wave the torch back and forth"],"A guide and steady speed produce straight cuts.")
H("821.d.6.G",3,"Which describes an acceptable oxy-fuel cut?","a smooth edge with square corners and little slag",["a rough, gouged edge","a heavy slag drip","a rounded top edge"],"Quality cuts are smooth and square.")
H("821.d.6.G",4,"Heavy slag clinging to the bottom of a cut usually shows the speed was:","too slow",["perfect","too fast to cut through","unrelated"],"Slow travel builds slag.")
H("821.d.6.H",3,"A shop compares acetylene with propane, propylene and MAPP-type gases for cutting. This is an evaluation of:","alternative fuel gases",["paint colors","helmet lenses","electrode coatings"],"Fuel choices differ in heat and cost.")
H("821.d.6.H",4,"A reason some shops choose propane over acetylene is that propane is usually:","lower in cost",["hotter in the inner cone","unable to burn","free of any hazard"],"Cost often drives fuel choice.")
H("821.d.7.A",3,"Before running a plasma cutter, Amir checks the work clamp, wears a face shield and keeps combustibles away. He is:","using safe operating practices",["setting a bid","drawing a part","packing a tool"],"Plasma cutting needs the same shop safety.")
H("821.d.7.A",4,"A plasma cutting operator should wear a shade-appropriate lens because the arc produces:","intense ultraviolet and visible light",["cold light","no light","only sound"],"Arc light injures eyes.")
H("821.d.7.B",3,"A plasma torch cuts metal by forcing gas through a small nozzle so that the gas becomes:","a hot, electrically conductive stream",["a cold liquid","a solid rod","a smooth foam"],"Plasma is an ionized gas.")
H("821.d.7.B",4,"Plasma arc cutting works on aluminum and stainless steel, unlike standard oxy-fuel cutting, because it:","melts the metal with an extremely hot arc rather than burning it",["uses paint","needs no electricity","freezes the metal"],"Plasma melts any conductive metal.")
H("821.d.7.C",3,"A plasma cutter requires a clean, dry air supply. If the compressed air has moisture, the cut will:","be rough and the consumables will wear faster",["be perfect","need less power","stop all arcs"],"Moisture harms cut quality.")
H("821.d.7.C",4,"Before connecting a plasma cutter to an air hose, the operator should:","check the pressure and drain the moisture filter",["remove the regulator","increase the pressure to the maximum","disconnect the ground"],"Proper air supply protects the torch.")
H("821.d.7.D",3,"The part of a plasma torch that wears out and must be replaced regularly, along with the electrode, is the:","nozzle or tip",["handle grip","power cord","ground clamp"],"Consumables include nozzle and electrode.")
H("821.d.7.D",4,"Which group lists consumable parts of a plasma torch?","electrode, nozzle and shield cup",["table, vise and clamp","helmet, gloves and jacket","drill, saw and hammer"],"These parts wear in use.")
H("821.d.7.E",3,"During set-up, the operator connects the work clamp to the base metal, sets the amperage for the thickness and adjusts the air pressure. This is the:","correct set-up procedure for plasma arc cutting",["shutdown procedure","cleanup step","packing step"],"Set-up follows manufacturer settings.")
H("821.d.7.E",4,"Cutting thicker steel with a plasma cutter generally requires:","higher amperage and slower travel",["lower amperage and faster travel","no amperage","no air"],"Thick metal needs more energy.")
H("821.d.7.F",3,"The width of metal removed by the cutting process is called:","the kerf",["the bead","the root","the leg"],"Kerf is the cut width.")
H("821.d.7.F",4,"The molten metal that sticks to the bottom edge of a cut is called:","dross",["flux","filler","slag glass"],"Dross is resolidified metal on a cut edge.")
H("821.d.7.G",3,"For an interior hole in a plate, a plasma cutter operator starts the cut with a:","pierce",["bend","tack","grind"],"Piercing starts a cut inside the plate.")
H("821.d.7.G",4,"To cut a beveled edge for a groove weld, the plasma torch is held:","at an angle to the plate surface",["upside down in the air","far from the plate","at a right angle only"],"Bevel cuts need a tilted torch.")
H("821.d.8.A",3,"Before striking an arc with a stick welder, Nia stands on a dry surface, checks her insulated gloves and places a screen around the area. This is:","safe operating practice",["a cost estimate","a drawing review","a delivery plan"],"Stick welding safety.")
H("821.d.8.A",4,"The electrode holder should be hung on an insulated hook while not in use so that it:","cannot touch the grounded table and cause an arc",["cools faster","looks neat only","stays warm"],"Live holders can arc.")
H("821.d.8.B",3,"On a stick welder, a setting where the current flows in one direction only is:","direct current",["alternating current","phase current","pulse current"],"DC flows one way.")
H("821.d.8.B",4,"With DC electrode positive (reverse polarity), the arc generally produces:","deeper base metal penetration",["no heat","shallower penetration only","no arc"],"DCEP gives deeper penetration.")
H("821.d.8.C",3,"In shielded metal arc welding, the coating on the electrode:","produces shielding gas and slag to protect the weld",["conducts heat away from the plate","paints the weld","cools the helmet"],"Flux shields the weld pool.")
H("821.d.8.C",4,"The rod stub length at which a welder normally stops welding to change electrodes is about:","two inches",["twelve inches","a full rod","zero inches"],"Short stubs are wasted and risk contact.")
H("821.d.8.D",3,"For a 1/8 in. E6013 electrode, the welder sets the amperage on the machine and checks polarity. This is part of:","proper set-up for shielded metal arc welding",["shutdown for the day","a safety walk-around","a bid review"],"Set-up depends on electrode and base metal.")
H("821.d.8.D",4,"If the amperage is set too high for the electrode size, the weld will likely show:","excessive spatter and undercut",["perfect penetration","no heat","cold lap"],"Too much current overheats the weld.")
H("821.d.8.E",3,"In the AWS classification E7018, the first two digits '70' refer to the electrode's:","minimum tensile strength of 70,000 psi",["diameter","length","brand"],"First digits give tensile strength.")
H("821.d.8.E",4,"The last two digits '18' in E7018 tell the welder about the:","coating type and usable current",["rod length","lot number","price"],"Last digits show coating and current type.")
H("821.d.8.F",3,"For welding thick structural steel that needs high strength and low hydrogen, a welder should choose:","an E7018 electrode",["an E6013 for tin","a bare wire","a brazing rod"],"E7018 is low hydrogen.")
H("821.d.8.F",4,"A welder selects electrodes by matching the rod's strength to the:","strength and type of the base metal",["color of the helmet","weight of the cart","name of the supplier"],"Match filler to base metal.")
H("821.d.8.G",3,"On a thick plate with a beveled groove, the welder lays a root pass, then fills with several more passes. This is:","a multi-pass groove weld",["a spot weld","a plug weld","a flange weld"],"Thick joints are welded in multiple passes.")
H("821.d.8.G",4,"Between passes on a multi-pass stick weld, the welder should:","remove the slag before the next pass",["leave the slag in place","quench the plate in water","add paint"],"Slag inclusions weaken welds.")
H("821.d.9.A",3,"Before starting a wire welder, Tomas checks gas flow, the drive rolls and the work area for flammables. He is:","using safe operating practices",["writing a bid","reading a catalog","cleaning a window"],"Pre-weld safety checks.")
H("821.d.9.A",4,"When welding with a shielding gas cylinder nearby, it should be:","chained upright and kept away from sparks",["laid flat","left loose","placed under the arc"],"Cylinder safety.")
H("821.d.9.B",3,"Tilting the gun to push the weld puddle instead of drag it changes the:","weld angle and bead shape",["wire color","gas type","helmet shade"],"Travel angle affects penetration.")
H("821.d.9.B",4,"If the electrode extension (stick-out) is too long on a wire welder, the result is typically:","less penetration and an unstable arc",["more penetration","no change","a quieter arc only"],"Long stick-out lowers current and heat.")
H("821.d.9.C",3,"In gas metal arc welding, the shielding gas is used to:","protect the molten weld pool from the air",["cool the wire spool","color the bead","feed the wire"],"Gas keeps oxygen and nitrogen out.")
H("821.d.9.C",4,"The consumable wire in a wire feed welder serves as:","the electrode and the filler metal",["only the shielding gas","only the ground","only the handle"],"Wire carries current and fills the joint.")
H("821.d.9.D",3,"A welder selects the wire size, threads it through the drive rolls and sets voltage and wire speed. This is:","proper set-up for gas metal arc welding",["a tear-down","a repair","a bid"],"Set-up before welding.")
H("821.d.9.D",4,"Shielding gas flow for GMAW is usually checked with a:","flowmeter on the regulator",["tape measure","micrometer","stopwatch"],"Flowmeters show cubic feet per hour.")
H("821.d.9.E",3,"In the wire classification ER70S-6, the '70' indicates:","a minimum tensile strength of 70,000 psi",["a diameter of 0.70 in.","a weight of 70 lb","a speed of 70 in/min"],"Same system as stick rods.")
H("821.d.9.E",4,"In ER70S-6, the 'S' means the wire is:","a solid wire",["a stick","a flux cored wire","a stainless wire"],"S = solid.")
H("821.d.9.F",3,"For welding mild steel with GMAW, a common filler is:","ER70S-6 solid wire",["an aluminum wire","a brass rod","a tungsten electrode"],"ER70S-6 suits mild steel.")
H("821.d.9.F",4,"Welding aluminum with GMAW requires matching the wire to the base metal, so the welder uses:","an aluminum filler wire",["a steel wire","a copper rod","no wire"],"Match filler to base metal.")
H("821.d.9.G",3,"A student welds a T-joint and a beveled butt joint in flat, horizontal, vertical and overhead positions. She is performing:","fillet and groove welds in all positions",["only tack welds","only flat welds","only cutting"],"All-position welding.")
H("821.d.9.G",4,"For a vertical weld with GMAW, a common practice is to:","use a lower heat setting and weave carefully",["use maximum heat","hold the gun backward","stop shielding gas"],"Lower heat prevents sagging.")
H("821.d.10.A",3,"A welder using flux cored wire on a field site checks her cables, gas needs and the fire hazards nearby. She is:","using safe operating practices",["setting a price","drawing a part","reading a code"],"Flux cored safety.")
H("821.d.10.A",4,"Fumes from flux cored welding are heavier than from solid wire, so the shop should provide:","adequate ventilation or fume extraction",["no airflow","a closed room","extra lighting only"],"Ventilation protects the welder.")
H("821.d.10.B",3,"Adjusting the gun angle and the stick-out when welding with flux cored wire changes the:","penetration and bead profile",["wire color","helmet shade","gas cylinder size"],"Angle and extension affect the weld.")
H("821.d.10.B",4,"A drag (backhand) travel angle on flux cored welding generally gives:","deeper penetration and a taller bead",["shallower penetration","no slag","no arc"],"Drag angle increases penetration.")
H("821.d.10.C",3,"Flux cored arc welding differs from solid-wire GMAW because the wire contains:","flux in its core that forms slag and shielding",["only copper","no metal","paint"],"The core provides protection.")
H("821.d.10.C",4,"Some flux cored wires, called self-shielded, can weld without:","an external shielding gas",["any electricity","a ground clamp","a helmet"],"Self-shielded wires create their own gas.")
H("821.d.10.D",3,"After loading flux cored wire, the welder sets the tension, polarity and wire speed for the diameter. This is:","proper set-up for flux cored arc welding",["a cleanup","a bid","a repair"],"Set-up before welding.")
H("821.d.10.D",4,"Many self-shielded flux cored wires run on:","DC electrode negative",["no current","DC electrode positive only","AC only"],"Self-shielded wires often use DCEN.")
H("821.d.10.E",3,"In the classification E71T-1, the 'T' tells the welder that the electrode is:","a tubular (flux cored) wire",["a solid wire","a brazing rod","a stick"],"T = tubular.")
H("821.d.10.E",4,"In E71T-1, the '7' shows the minimum tensile strength is:","70,000 psi",["7,000 psi","700 psi","700,000 psi"],"Same system as other AWS electrodes.")
H("821.d.10.F",3,"A welder picking filler for mild steel with flux cored welding should match the:","wire classification to the base metal strength",["wire color to the plate","spool weight to the gun","price to the table"],"Match filler to base metal.")
H("821.d.10.F",4,"For outdoor, windy conditions on mild steel, a good filler is:","a self-shielded flux cored wire",["a solid wire with gas only","a tungsten rod","a bare brazing rod"],"No gas to blow away.")
H("821.d.10.G",3,"A student welds T-joint fillets and beveled groove joints with flux cored wire in each position. This is:","fillet and groove welds in all positions",["only tacking","only grinding","only gouging"],"All-position practice.")
H("821.d.10.G",4,"After each flux cored pass, the welder should:","remove the slag before the next pass",["leave it on","paint it","quench it"],"Slag must be cleaned.")
H("821.d.11.A",3,"Before starting a TIG weld, Caleb checks the gas hose, puts on a helmet with a suitable lens and clears the area of solvent. He is:","using safe operating practices",["setting a bid","reading a menu","planning lunch"],"GTAW safety.")
H("821.d.11.A",4,"Cleaning solvents such as those containing chlorine must be kept away from TIG welding because arc light can turn them into:","toxic gases",["pure water","smooth metal","nothing"],"Chlorinated solvents form phosgene.")
H("821.d.11.B",3,"When TIG welding aluminum, a welder normally selects:","alternating current",["direct current only","no current","pulse only on steel"],"AC cleans the oxide layer.")
H("821.d.11.B",4,"For most steel and stainless steel TIG welding, the common current is:","DC electrode negative",["AC only","DC electrode positive","no current"],"DCEN gives deep penetration.")
H("821.d.11.C",3,"A welder uses a 2% thoriated or lanthanated tungsten for steel. She is identifying:","a common type of tungsten electrode",["a type of paint","a type of cable","a type of table"],"Tungsten types are color coded.")
H("821.d.11.C",4,"A filler rod classified ER308 is generally used to weld:","stainless steel",["aluminum","cast iron","copper"],"308 matches 304 stainless.")
H("821.d.11.D",3,"The welder grinds the tungsten to a point, sets the gas flow, selects the current and checks the foot pedal. This is:","proper set-up for gas tungsten arc welding",["a shutdown","a tool storage","a pricing step"],"Set-up before welding.")
H("821.d.11.D",4,"The shielding gas most often used for TIG welding is:","argon",["oxygen","acetylene","hydrogen alone"],"Argon is the standard.")
H("821.d.11.E",3,"A student TIG welds fillet and groove joints in all four positions. She is:","performing welds in all positions",["only brazing","only cutting","only grinding"],"All-position proficiency.")
H("821.d.11.E",4,"A TIG welder keeps the filler rod's hot end:","inside the shielding gas envelope",["outside it","in the air","in water"],"Prevents contamination.")
H("821.d.11.F",3,"A shop uses TIG on thin carbon steel, stainless and aluminum parts. This shows welding on:","a variety of metals",["only one metal","wood","plastic"],"TIG works on many metals.")
H("821.d.11.F",4,"Before TIG welding aluminum, the surface should be cleaned of:","oxide and contaminants",["clean metal only","shiny finish","nothing"],"Oxide melts at a higher temperature.")

B.balance()
